// 144-rule synthetic catalog across 8 categories. Original to this workspace —
// generated deterministically (no randomness) from per-category phrase banks so
// every rule is inspectable in source rather than templated at runtime with Math.random().
// Six "anchor" rules (R1, R4, R7, R17, R73, R88) are hand-written and carry a
// human-readable `anchor` label; everything else is generated by combining
// subject/pattern/qualifier banks 3x3x2 = 18 per category, matching the 8x18=144 total.

import type { Category, Rule, Severity } from "./types";

export const CATEGORIES: Category[] = [
  "Workload & Burnout",
  "Velocity & Delivery",
  "Financial & Austerity",
  "Trust & Psychological Safety",
  "Communication & Information Flow",
  "Culture & Alignment",
  "Succession & Continuity",
  "Compliance & Governance",
];

const BANKS: Record<Category, { subjects: string[]; patterns: string[]; qualifiers: [string, Severity][] }> = {
  "Workload & Burnout": {
    subjects: ["An individual contributor", "A team lead", "An on-call rotation"],
    patterns: [
      "shows sustained after-hours activity with no compensating recovery window",
      "has absorbed a departed colleague's workload without backfill",
      "reports declining task-completion quality under flat deadlines",
    ],
    qualifiers: [["for 2+ consecutive weeks", "medium"], ["for 4+ consecutive weeks", "high"]],
  },
  "Velocity & Delivery": {
    subjects: ["A delivery team", "A release train", "A cross-functional squad"],
    patterns: [
      "is cutting scope repeatedly to hit immovable dates",
      "shows cycle time increasing while story count stays flat",
      "is accumulating rework from skipped review steps",
    ],
    qualifiers: [["for 1 sprint", "low"], ["for 3+ consecutive sprints", "high"]],
  },
  "Financial & Austerity": {
    subjects: ["A cost center", "A discretionary budget line", "A vendor contract"],
    patterns: [
      "has been cut without a corresponding scope reduction",
      "is being renewed at reduced headcount while scope grows",
      "shows spend concentrated in the final weeks of the cycle (use-it-or-lose-it)",
    ],
    qualifiers: [["minor variance", "low"], ["major variance against plan", "high"]],
  },
  "Trust & Psychological Safety": {
    subjects: ["A team", "A direct report", "A cross-team dependency pair"],
    patterns: [
      "shows a drop in dissenting input during planning meetings",
      "has an unresolved conflict that was never surfaced to a manager",
      "shows declining voluntary status updates (signal of disengagement)",
    ],
    qualifiers: [["isolated instance", "low"], ["recurring pattern", "high"]],
  },
  "Communication & Information Flow": {
    subjects: ["A manager", "A project channel", "A stakeholder group"],
    patterns: [
      "is the sole conduit for information between two teams (single point of failure)",
      "shows decisions made without a documented record",
      "shows meeting attendance dropping while decision load rises",
    ],
    qualifiers: [["localized", "medium"], ["spanning multiple teams", "high"]],
  },
  "Culture & Alignment": {
    subjects: ["A team", "A newly merged org unit", "A long-tenured group"],
    patterns: [
      "shows stated values diverging from observed prioritization",
      "has two sub-groups optimizing for conflicting metrics",
      "shows onboarding feedback trending negative on 'how we work here'",
    ],
    qualifiers: [["early signal", "low"], ["confirmed by multiple sources", "medium"]],
  },
  "Succession & Continuity": {
    subjects: ["A critical role", "A tenured leader", "A key technical domain"],
    patterns: [
      "has no identified backup or successor",
      "holds undocumented tribal knowledge critical to operations",
      "shows a flight-risk indicator with no retention conversation on record",
    ],
    qualifiers: [["single point of failure, low urgency", "medium"], ["single point of failure, high urgency", "high"]],
  },
  "Compliance & Governance": {
    subjects: ["A decision-rights boundary", "An approval workflow", "A policy exception"],
    patterns: [
      "is being routinely bypassed under time pressure",
      "lacks an audit trail for a materially impactful decision",
      "has an exception granted without a documented expiry or review date",
    ],
    qualifiers: [["procedural", "low"], ["material governance gap", "high"]],
  },
};

// Anchor IDs are deliberately the first slot(s) of their category's numeric
// range (see CATEGORIES order + RULES_PER_CATEGORY=18 below) so they can never
// collide with a generated ID. R1/R2 = Workload (range 1-18), R19 = Velocity
// (range 19-36), R37 = Financial (range 37-54), R55/R56 = Trust (range 55-72).
const ANCHORS: Rule[] = [
  {
    id: "R1",
    category: "Workload & Burnout",
    title: "Sustained overload with no recovery window",
    description:
      "A person carries load above sustainable baseline for an extended period with no scheduled recovery — the seed condition for a burnout loop.",
    baseSeverity: "high",
    anchor: "burnout loop — root node",
  },
  {
    id: "R2",
    category: "Workload & Burnout",
    title: "Overload compounded by withdrawal of support",
    description:
      "The same person flagged for overload is also showing reduced help-seeking behavior — load and isolation reinforcing each other.",
    baseSeverity: "high",
    anchor: "burnout loop — reinforcing node",
  },
  {
    id: "R19",
    category: "Velocity & Delivery",
    title: "Compounding scope cuts under fixed deadlines",
    description:
      "Repeated scope-cutting to preserve a date, with each cut increasing pressure on the next cycle — the seed condition for a velocity death spiral.",
    baseSeverity: "high",
    anchor: "velocity death spiral — root node",
  },
  {
    id: "R37",
    category: "Financial & Austerity",
    title: "Budget cuts without matching scope reduction",
    description:
      "Cost reduced while commitments stay fixed, pushing the gap onto people — the seed condition for an austerity trap.",
    baseSeverity: "high",
    anchor: "austerity trap — root node",
  },
  {
    id: "R55",
    category: "Trust & Psychological Safety",
    title: "Dissent suppressed in group settings",
    description:
      "Disagreement no longer surfaces in shared forums; it either goes silent or moves to private backchannels.",
    baseSeverity: "medium",
    anchor: "trust collapse — early signal",
  },
  {
    id: "R56",
    category: "Trust & Psychological Safety",
    title: "Confirmed withdrawal of voluntary disclosure",
    description:
      "People who previously volunteered risks or mistakes have stopped doing so across more than one reporting cycle — trust collapse confirmed.",
    baseSeverity: "high",
    anchor: "trust collapse — confirmed",
  },
];

const RULES_PER_CATEGORY = 18; // 8 categories x 18 = 144

function buildGenerated(): Rule[] {
  const out: Rule[] = [];
  let counter = 1;
  for (const category of CATEGORIES) {
    const bank = BANKS[category];
    const anchorsInCategory = ANCHORS.filter((a) => a.category === category);
    const anchorIds = anchorsInCategory.map((a) => a.id);
    const needed = RULES_PER_CATEGORY - anchorsInCategory.length;
    const slots: Rule[] = [];
    outer: for (const subject of bank.subjects) {
      for (const pattern of bank.patterns) {
        for (const [qualifier, severity] of bank.qualifiers) {
          if (slots.length >= needed) break outer;
          slots.push({
            id: "", // assigned below
            category,
            title: `${subject} ${pattern}`.slice(0, 1).toUpperCase() + `${subject} ${pattern}`.slice(1),
            description: `${subject} ${pattern}, ${qualifier}.`,
            baseSeverity: severity,
          });
        }
      }
    }
    // Assign sequential IDs for this category's generated slots, skipping any
    // ID already reserved by an anchor rule so IDs never collide, and reserving
    // exactly RULES_PER_CATEGORY ids total (generated + anchors) per category.
    let assigned = 0;
    const categoryStart = counter;
    while (assigned < RULES_PER_CATEGORY) {
      const candidateId = `R${counter}`;
      counter += 1;
      if (anchorIds.includes(candidateId)) {
        assigned += 1;
        continue;
      }
      const rule = slots.shift();
      if (!rule) break;
      rule.id = candidateId;
      out.push(rule);
      assigned += 1;
    }
    void categoryStart;
  }
  return out;
}

export function buildCatalog(): Rule[] {
  const generated = buildGenerated();
  const byId = new Map<string, Rule>();
  for (const r of generated) byId.set(r.id, r);
  for (const a of ANCHORS) byId.set(a.id, a); // anchors win on collision
  // Re-sort numerically by ID so the catalog reads R1..R144 in order.
  return Array.from(byId.values()).sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
}

export const RULES: Rule[] = buildCatalog();

export function rulesByCategory(category: Category): Rule[] {
  return RULES.filter((r) => r.category === category);
}

export function getRule(id: string): Rule | undefined {
  return RULES.find((r) => r.id === id);
}
